import * as z from "zod/v4";
import { ASTRO_PLUGIN_DEFAULTS } from "./defaults.js";
const EntrypointSchema = z.union([z.string(), z.instanceof(URL)]);
const OptimizeDepsSchema = z.object({
	include: z.array(z.string()).optional(),
	exclude: z.array(z.string()).optional()
});
/**
* Validates `AstroPluginOptions` and applies defaults. The `astro` CLI config schema reuses the
* field schemas through `AstroPluginOptionsSchema.shape`.
*/
export const AstroPluginOptionsSchema = z.object({
	root: z.string().optional(),
	publicDir: z.string().optional().default(ASTRO_PLUGIN_DEFAULTS.publicDir),
	site: z.string().url().optional(),
	compressHTML: z.union([z.boolean(), z.literal("jsx")]).optional().default(ASTRO_PLUGIN_DEFAULTS.compressHTML),
	trailingSlash: z.union([
		z.literal("always"),
		z.literal("never"),
		z.literal("ignore")
	]).optional().default(ASTRO_PLUGIN_DEFAULTS.trailingSlash),
	renderers: z.array(z.object({
		name: z.string(),
		// Renderers of integrations may set `null`.
		clientEntrypoint: EntrypointSchema.nullish(),
		serverEntrypoint: EntrypointSchema,
		options: z.unknown().optional(),
		optimizeDeps: z.object({
			client: OptimizeDepsSchema.optional(),
			server: OptimizeDepsSchema.optional()
		}).optional(),
		dedupe: z.array(z.string()).optional(),
		noExternal: z.union([z.array(z.string()), z.custom((value) => typeof value === "function")]).optional(),
		devHeadScript: z.string().optional(),
		appEntrypoint: z.string().optional(),
		appEntrypointImporters: z.instanceof(RegExp).optional()
	})).optional().default([]),
	clientDirectives: z.array(z.object({
		name: z.string(),
		entrypoint: EntrypointSchema
	})).optional().default([])
});
